using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

builder.Services.AddSingleton<ModelTrainerService>();

// Train the model at startup so the pool has a file to load.
using (var startupServices = builder.Services.BuildServiceProvider())
{
    var trainer = startupServices.GetRequiredService<ModelTrainerService>();
    trainer.TrainAndSaveModel();
}

var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

